CREATE TABLE "teach_applications" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "teach_applications_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"submit_id" text NOT NULL,
	"name" text NOT NULL,
	"email" text NOT NULL,
	"phone" text NOT NULL,
	"country" text NOT NULL,
	"gender" text NOT NULL,
	"courses" text[] NOT NULL,
	"languages" text[] NOT NULL,
	"qualifications" text[] NOT NULL,
	"qualification_other" text,
	"ijazah" boolean NOT NULL,
	"ijazah_detail" text,
	"experience" text NOT NULL,
	"availability" text NOT NULL,
	"time_zone" text NOT NULL,
	"sample_url" text,
	"referees" text,
	"message" text,
	"status" text DEFAULT 'new' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "teach_applications_gender" CHECK (gender IN ('male', 'female')),
	CONSTRAINT "teach_applications_status" CHECK (status IN ('new', 'contacted', 'closed')),
	CONSTRAINT "teach_applications_submit_format" CHECK ("teach_applications"."submit_id" ~ '^[A-Za-z0-9-]{16,64}$'),
	CONSTRAINT "teach_applications_lists" CHECK (cardinality("teach_applications"."courses") > 0 AND cardinality("teach_applications"."languages") > 0 AND cardinality("teach_applications"."qualifications") > 0),
	CONSTRAINT "teach_applications_sample_https" CHECK ("teach_applications"."sample_url" IS NULL OR "teach_applications"."sample_url" ~ '^https://')
);
--> statement-breakpoint
CREATE UNIQUE INDEX "teach_applications_submit_uq" ON "teach_applications" USING btree ("submit_id");--> statement-breakpoint
CREATE INDEX "teach_applications_email_idx" ON "teach_applications" USING btree (lower("email"));